#!/usr/bin/env bash
set -euo pipefail

# Regenerates Sources/RoadSecretsCore/WordLists.swift from Resources/adjectives.txt and nouns.txt.
# The text files are the source of truth and the ones a person reviews. The lists are compiled into
# the binary so that the installed copy in ~/.local/bin needs no resource bundle beside it.
# A unit test fails if the generated file and the text files disagree.

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
OUT="${ROOT}/Sources/RoadSecretsCore/WordLists.swift"

emit() {
  local name="$1" file="$2"
  printf '    public static let %s: [String] = [\n' "${name}"
  grep -v '^[[:space:]]*$' "${file}" | awk '{ printf "        \"%s\",\n", $0 }'
  printf '    ]\n'
}

{
  printf '// Generated by scripts/gen-wordlists.sh from Resources/*.txt. Do not edit by hand.\n\n'
  printf 'public enum WordLists {\n'
  emit adjectives "${ROOT}/Resources/adjectives.txt"
  printf '\n'
  emit nouns "${ROOT}/Resources/nouns.txt"
  printf '}\n'
} > "${OUT}"

echo "[INFO] wrote ${OUT}"
